#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> factorials, invFactorials;

long long powMod(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

void prepareFactorials() {
    factorials.resize(200001);
    invFactorials.resize(200001);
    factorials[0] = 1;
    invFactorials[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        factorials[i] = (factorials[i - 1] * i) % MOD;
        invFactorials[i] = powMod(factorials[i], MOD - 2, MOD);
    }
}

long long ncr(int n, int r) {
    return (((factorials[n] * invFactorials[r]) % MOD) * invFactorials[n - r]) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    prepareFactorials();

    long long n, k;
    cin >> n >> k;

    if (k > n) {
        cout << 0 << "\n";
        return 0;
    }

    long long diff = n - k;
    long long totalSum = 0;

    for (int i = 0; i <= diff; i++) {
        long long term = (ncr((int)diff, i) * powMod(diff - i, n, MOD)) % MOD;
        if (i % 2 == 0)
            totalSum += term;
        else
            totalSum -= term;
        totalSum = (totalSum + MOD) % MOD;
    }

    long long result = (totalSum * ncr((int)n, (int)diff)) % MOD;

    if (diff == 0)
        cout << result << "\n";
    else
        cout << (2 * result) % MOD << "\n";

    return 0;
}
